// Server Component - No useEffect or client bundle overhead
import { Suspense } from 'react';
import MetricsSkeleton from '@/components/MetricsSkeleton';

async function LiveMetrics() {
  // Cached fetch with incremental revalidation
  const res = await fetch('https://api.example.com/analytics', {
    next: { revalidate: 60 } // Revalidate every 60s
  });
  const data = await res.json();

  return (
    <div className="grid grid-cols-3 gap-4">
      {data.metrics.map(item => (
        <div key={item.id} className="p-4 rounded-xl bg-neutral-900 border border-neutral-800">
          <h3 className="text-sm text-neutral-400">{item.label}</h3>
          <p className="text-2xl font-bold text-white">{item.value}</p>
        </div>
      ))}
    </div>
  );
}

export default function DashboardPage() {
  return (
    <main className="p-8 max-w-5xl mx-auto">
      <h1 className="text-3xl font-bold mb-6">Analytics Overview</h1>
      <Suspense fallback={<MetricsSkeleton />}>
        <LiveMetrics />
      </Suspense>
    </main>
  );
}

// Use startTransition to yield control back to the main thread
import { useTransition } from 'react';

function SearchInterface() {
  const [isPending, startTransition] = useTransition();
  const [results, setResults] = useState([]);

  const handleSearch = (e) => {
    const query = e.target.value;
    // Urgent: input update shows immediately
    setInputValue(query);

    // Non-urgent: deferred update does not block user typing or UI painting
    startTransition(() => {
      const filtered = performHeavyComputation(query);
      setResults(filtered);
    });
  };

  return <input onChange={handleSearch} />;
}

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export const useCartStore = create(
  persist(
    (set, get) => ({
      items: [],
      addItem: (product) =>
        set((state) => ({
          items: [...state.items, product],
        })),
      removeItem: (id) =>
        set((state) => ({
          items: state.items.filter((i) => i.id !== id),
        })),
      clearCart: () => set({ items: [] }),
      getTotal: () =>
        get().items.reduce((sum, item) => sum + item.price, 0),
    }),
    { name: 'shopping-cart-storage' }
  )
);
